{"implementation":"def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]
    n = len(nodes)
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core distance for {node}")
    edges = []
    for a, b, d in distances:
        if a == b:
            continue
        left, right = (a, b) if a < b else (b, a)
        w = max(core_distance[left], core_distance[right], d)
        edges.append((w, left, right))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    selected = []
    total = 0.0
    for w, a, b in edges:
        if union(a, b):
            selected.append([a, b, w])
            total += w
            if len(selected) == n - 1:
                break
    if len(selected) != n - 1:
        raise ValueError("Graph is disconnected, cannot form MST")
    return {"edges": selected, "total_weight": total}"}
